'use strict';
/**
 * One-click connection files for external database GUIs — DBeaver first,
 * the one mechanism confirmed today against DBeaver's own docs: its `-con`
 * CLI flag opens a connection that is *ephemeral by default* (`save=false`)
 * — it never touches DBeaver's own `data-sources.json` unless `save=true`
 * is passed, which this never does.
 *
 * The generated file is a plain shell script, not a ServerLife-specific
 * format: it starts its own `tsh proxy db --tunnel` (the same no-password
 * trust model dbproxy.js uses), waits for the port tsh prints, launches the
 * GUI pointed at it, and keeps the tunnel open — in its own terminal
 * window — for as long as the GUI needs it. Nothing here depends on
 * ServerLife still running.
 */

const fs = require('fs');
const path = require('path');
const os = require('os');
const { spawn } = require('child_process');
const teleport = require('./teleport');

const OUT_DIR = path.join(os.homedir(), 'Downloads');

// DBeaver's own driver ids — confirmed for postgres/mysql against its
// wiki's own examples; the others follow the same well-known convention
// but were not individually re-confirmed today.
const DBEAVER_DRIVER = {
  postgres: 'postgresql',
  mysql: 'mysql',
  sqlserver: 'mssql',
  mongodb: 'mongodb',
  redis: 'redis',
  cassandra: 'cassandra',
};

function safeName(s) {
  return String(s || 'database').replace(/[^\w.-]+/g, '_');
}

function shellQuote(s) {
  return `'${String(s).replace(/'/g, `'\\''`)}'`;
}

function dbeaverScript({ resourceName, proxy, dbUser, dbNameParam, protocol }) {
  const driver = DBEAVER_DRIVER[protocol];
  if (!driver) throw new Error(`No DBeaver driver mapping for protocol "${protocol}" yet.`);
  const tshArgs = [
    'proxy', 'db', '--tunnel', '--port=0', '--db-user=' + dbUser,
    ...(dbNameParam ? ['--db-name=' + dbNameParam] : []),
    ...(proxy ? ['--proxy=' + proxy] : []),
    resourceName,
  ];
  const tshCommand = [shellQuote(teleport.findTsh()), ...tshArgs.map(shellQuote)].join(' ');
  // user= is required — without it DBeaver defaults to the OS login name,
  // which is never a real database role, and Postgres refuses with "role
  // <os-user> does not exist". Confirmed live: this was missing and that
  // exact error is what showed up.
  const conParts = [`driver=${driver}`, 'host=localhost', 'port=$PORT', `user=${dbUser}`];
  if (dbNameParam) conParts.push(`database=${dbNameParam}`);
  conParts.push('connect=true');

  return `#!/bin/bash
# Generated by ServerLife — one-click DBeaver connection to "${resourceName}"
# through Teleport. No password: the tunnel is already authenticated, and
# nothing is saved into DBeaver's own connection list (its -con flag is
# ephemeral unless save=true is passed, which this never does).
set -e
LOG="$(mktemp)"
${tshCommand} > "$LOG" 2>&1 &
TSH_PID=$!
trap 'kill $TSH_PID 2>/dev/null' EXIT

PORT=""
for i in $(seq 1 50); do
  PORT=$(grep 'Started authenticated tunnel' "$LOG" | tail -1 | sed -E 's/.* on [^:]+:([0-9]+)\\..*/\\1/')
  [ -n "$PORT" ] && break
  sleep 0.2
done
if [ -z "$PORT" ]; then
  echo "Could not start the Teleport tunnel:"
  cat "$LOG"
  read -p "Press Enter to close..." _
  exit 1
fi

# DBeaver runs a single-instance "instance server" and hands a second
# launch's -con straight to the window it already has open instead of
# opening this one — confirmed live: with DBeaver already running, -con
# (with or without open -n) silently did nothing. Closing it first is the
# only way found to make a second -con actually take effect.
if pgrep -f "DBeaver.app/Contents/MacOS/dbeaver" > /dev/null 2>&1; then
  echo "DBeaver is already running and would otherwise ignore this connection — closing it first…"
  # Backgrounded: a dialog already open in DBeaver (e.g. from a previous
  # failed connection) can make a graceful quit hang indefinitely, which
  # would otherwise stall this whole script forever.
  osascript -e 'tell application "DBeaver" to quit' > /dev/null 2>&1 &
  for i in $(seq 1 30); do
    pgrep -f "DBeaver.app/Contents/MacOS/dbeaver" > /dev/null 2>&1 || break
    sleep 0.3
  done
  if pgrep -f "DBeaver.app/Contents/MacOS/dbeaver" > /dev/null 2>&1; then
    echo "DBeaver didn't close in time (a dialog may be open) — closing it by force."
    pkill -f "DBeaver.app/Contents/MacOS/dbeaver" 2>/dev/null || true
    sleep 1
  fi
fi

echo "Tunnel open on localhost:$PORT — launching DBeaver. Keep this window open while you use it."
open -a "DBeaver" --args -con "${conParts.join('|')}"
wait "$TSH_PID"
`;
}

/**
 * `spec` is the Teleport database reference ({name, protocol, proxy});
 * `opts` carries {dbUser, dbNameParam}. Only `target: 'dbeaver'` exists
 * so far — pgAdmin (official `load-servers` loader) and DataGrip
 * (VCS-shareable dataSources.xml) are the next two, not yet built.
 */
function writeLauncher(spec = {}, opts = {}, target) {
  const resourceName = spec.name;
  const { dbUser, dbNameParam } = opts;
  if (!resourceName) throw new Error('No database to export.');
  if (!dbUser) throw new Error('No database user to export with — fill that in first.');
  if (target !== 'dbeaver') throw new Error(`"${target}" isn't supported yet — only DBeaver is.`);
  const script = dbeaverScript({
    resourceName, proxy: spec.proxy, dbUser, dbNameParam, protocol: spec.protocol,
  });
  fs.mkdirSync(OUT_DIR, { recursive: true });
  const file = path.join(OUT_DIR, `${safeName(resourceName)}-dbeaver.command`);
  fs.writeFileSync(file, script, { mode: 0o755 });
  return { ok: true, path: file };
}

/**
 * Launchers started from here, tracked so the sidebar can show "a tunnel
 * for this database is running" instead of leaving it invisible — the
 * exact confusion a real run turned up: Test and Connect already keep a
 * tunnel open in the background after they return (dbproxy.js reuses it
 * on purpose), and an exported launcher's tunnel is a second, completely
 * separate process ServerLife otherwise has no record of at all.
 * resourceName -> { pid, startedAt }
 */
const running = new Map();

/**
 * Runs an already-written launcher immediately — detached, so it (and the
 * tunnel it starts) keeps running on its own even after ServerLife closes,
 * same as double-clicking it in Finder would. Verified directly: the real
 * Postgres container's own pg_stat_activity showed DBeaver connected as
 * the right user and running its own navigator query, with no manual step
 * beyond this one click.
 */
function runLauncher(filePath, resourceName) {
  if (!filePath || !fs.existsSync(filePath)) throw new Error('That launcher file no longer exists.');
  const child = spawn('/bin/bash', [filePath], { detached: true, stdio: 'ignore' });
  child.unref();
  if (resourceName) running.set(resourceName, { pid: child.pid, startedAt: Date.now() });
  return { ok: true, pid: child.pid };
}

/** Is the pid from an earlier runLauncher() still actually alive? */
function pidAlive(pid) {
  try { process.kill(pid, 0); return true; } catch { return false; }
}

/** Launcher-started tunnels believed still running, for a status badge. */
function status() {
  for (const [name, r] of running) if (!pidAlive(r.pid)) running.delete(name);
  return [...running.entries()].map(([resourceName, r]) => ({ resourceName, pid: r.pid, startedAt: r.startedAt }));
}

function stop(resourceName) {
  const r = running.get(resourceName);
  if (!r) return false;
  try { process.kill(r.pid); } catch { /* already exited */ }
  running.delete(resourceName);
  return true;
}

module.exports = { writeLauncher, runLauncher, status, stop, DBEAVER_DRIVER };
